uml:
@startuml
title 2.1 End-to-End Procurement and Inbound Receiving (BF-01)

scale 2000 width

skinparam shadowing false
skinparam defaultFontName Arial
skinparam defaultFontSize 11
skinparam activityFontSize 11
skinparam swimlaneWidth 260
skinparam activityBorderColor #666666
skinparam activityBackgroundColor #FDFDFD
skinparam activityDiamondBackgroundColor #FFF4D6
skinparam activityDiamondBorderColor #888888
skinparam activityArrowColor #666666

|Inventory Staff|
start
:Review stock level;

|System|
:Show available stock,\nminimum level and pending inbound;

if (Stock below required level?) then (Yes)

    |Inventory Staff|
    :Determine required quantity;
    :Create Purchase Request;

    |System|
    :Validate product and quantity;
    :Check existing open orders;
    :Submit request to Accountant;

    |Accountant|
    :Review Purchase Request;

    if (Approve request?) then (Yes)

        :Select supplier;
        :Create Purchase Order;
        :Enter price and expected date;

        |System|
        :Validate Purchase Order;
        :Create approved Purchase Order;
        :Record order status;

        |Accountant|
        :Send Purchase Order to supplier\nthrough external channel;
        :Record supplier confirmation;

        |System|
        :Update confirmed quantity\nand expected delivery date;

        |Inventory Staff|
        :Receive delivered goods;
        :Open related Purchase Order;
        :Check product and quantity;
        :Check lot, color and condition;

        |System|
        :Compare actual receipt\nwith Purchase Order;

        if (Receiving discrepancy?) then (Yes)

            |Inventory Staff|
            :Record discrepancy;

            |Accountant|
            :Review discrepancy;
            :Contact supplier externally;
            :Record handling result;

            |System|
            :Update accepted and\noutstanding quantities;

        endif

        |Inventory Staff|
        :Create or select lot;
        :Create Goods Receipt Note;
        :Select receiving warehouse;
        :Assign storage location;
        :Confirm actual receipt;

        |System|
        :Validate Goods Receipt Note;
        :Increase stock by warehouse,\nlot and location;
        :Update Purchase Order progress;
        :Record inventory transaction;

        |Accountant|
        :Receive supplier invoice;
        :Verify invoice against\nPurchase Order and receipt;
        :Record payable information;

        |System|
        :Update payable record;

        if (Purchase Order fully received?) then (Yes)
            :Set Purchase Order\nas Completed;
        else (No)
            :Set Purchase Order\nas Partially Received;
        endif

    else (No)

        |System|
        :Set Purchase Request\nas Rejected;
        :Notify Inventory Staff;

    endif

else (No)

    |System|
    :No replenishment required;

endif

stop
@enduml
